operation.add:
// SvetLamp power filter: the powers present in this category and the ones chosen
$sl_power = array();

if (!empty($this->request->get['power'])) {
	foreach (explode(',', $this->request->get['power']) as $sl_value) {
		$sl_value = trim($sl_value);

		if ($sl_value !== '' && !in_array($sl_value, $sl_power)) {
			$sl_power[] = $sl_value;
		}
	}
}

$data['sl_power_options'] = array();
$data['sl_power_reset'] = '';

$sl_attribute = $this->db->query("SELECT attribute_id FROM `" . DB_PREFIX . "attribute_description` WHERE name = 'Мощность лампы' LIMIT 1");

if ($sl_attribute->num_rows) {
	$sl_values = $this->db->query("SELECT pa.text, COUNT(DISTINCT p.product_id) AS total FROM `" . DB_PREFIX . "product_attribute` pa LEFT JOIN `" . DB_PREFIX . "product_to_category` p2c ON (p2c.product_id = pa.product_id) LEFT JOIN `" . DB_PREFIX . "product` p ON (p.product_id = pa.product_id) LEFT JOIN `" . DB_PREFIX . "product_to_store` p2s ON (p2s.product_id = p.product_id) WHERE p2c.category_id = '" . (int)$category_id . "' AND pa.attribute_id = '" . (int)$sl_attribute->row['attribute_id'] . "' AND pa.language_id = '" . (int)$this->config->get('config_language_id') . "' AND TRIM(pa.text) <> '' AND p.status = '1' AND p.date_available <= NOW() AND p2s.store_id = '" . (int)$this->config->get('config_store_id') . "' GROUP BY pa.text ORDER BY CAST(REPLACE(pa.text, ',', '.') AS DECIMAL(10,2)), pa.text");

	if ($sl_values->num_rows > 1) {
		// Sorting and page size stay, the page number starts again
		$sl_url = '';

		if (isset($this->request->get['sort'])) {
			$sl_url .= '&sort=' . $this->request->get['sort'];
		}

		if (isset($this->request->get['order'])) {
			$sl_url .= '&order=' . $this->request->get['order'];
		}

		if (isset($this->request->get['limit'])) {
			$sl_url .= '&limit=' . $this->request->get['limit'];
		}

		foreach ($sl_values->rows as $sl_row) {
			$sl_active = in_array($sl_row['text'], $sl_power);
			$sl_next = $sl_active ? array_values(array_diff($sl_power, array($sl_row['text']))) : array_merge($sl_power, array($sl_row['text']));

			$data['sl_power_options'][] = array(
				'name'   => str_replace('.', ',', $sl_row['text']) . ' Вт',
				'total'  => (int)$sl_row['total'],
				'active' => $sl_active,
				'href'   => $this->url->link('product/category', 'path=' . $this->request->get['path'] . $sl_url . ($sl_next ? '&power=' . urlencode(implode(',', $sl_next)) : ''))
			);
		}

		if ($sl_power) {
			$data['sl_power_reset'] = $this->url->link('product/category', 'path=' . $this->request->get['path'] . $sl_url);
		}
	}
}

// SvetLamp power filter
if (!empty($data['filter_sl_power'])) {
	$sl_values = array();

	foreach ($data['filter_sl_power'] as $sl_value) {
		$sl_values[] = "'" . $this->db->escape($sl_value) . "'";
	}

	$sql .= " AND p.product_id IN (SELECT pa.product_id FROM `" . DB_PREFIX . "product_attribute` pa LEFT JOIN `" . DB_PREFIX . "attribute_description` ad ON (ad.attribute_id = pa.attribute_id AND ad.language_id = pa.language_id) WHERE ad.name = 'Мощность лампы' AND pa.language_id = '" . (int)$this->config->get('config_language_id') . "' AND pa.text IN (" . implode(',', $sl_values) . "))";
}
